<?php
declare(strict_types=1);namespace App\Application\Payments;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Models\{PaymentIntentRecord,Proposal,Tenant,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class PaymentRequestService{public function __construct(private AuditWriter$audit,private OutboxWriter$outbox){}public function create(Tenant$t,Proposal$p,array$d,User$actor):PaymentIntentRecord{if($p->tenant_id!==$t->id||$p->status!=='PAYMENT_PENDING')throw ValidationException::withMessages(['proposal_id'=>__('wave3.payment_not_eligible')]);if($existing=PaymentIntentRecord::where(['tenant_id'=>$t->id,'idempotency_key'=>$d['idempotency_key']])->first())return$existing;return DB::transaction(function()use($t,$p,$d,$actor){$amount=(int)$p->terms_snapshot['total_minor'];$intent=PaymentIntentRecord::create(['tenant_id'=>$t->id,'proposal_id'=>$p->id,'provider'=>$d['provider'],'payer_phone_e164'=>$d['payer_phone_e164'],'amount_minor'=>$amount,'currency'=>$p->terms_snapshot['currency'],'status'=>'PENDING_CUSTOMER','idempotency_key'=>$d['idempotency_key'],'provider_snapshot'=>[],'requested_by'=>$actor->id,'expires_at'=>now()->addMinutes(15),'customer_prompted_at'=>now(),'request_channel'=>'WEB']);$this->audit->record('payment.requested','payment_intent',$intent->id,['amount_minor'=>$amount,'provider'=>$d['provider']]);$this->outbox->record('payment.requested','payment_intent',$intent->id,['payment_intent_id'=>$intent->id,'proposal_id'=>$p->id,'provider'=>$d['provider']]);return$intent;});}}
